const unique = new Map(LINKS.map((link) => [link.href, link]))
const checkable = [...unique.values()].filter((link) => link.status > 0)

export const STATS = {
  links: LINKS.length,
  unique: unique.size,
  external: new Set(
    LINKS.filter((link) => link.group === 'external').map((link) => new URL(link.href).hostname),
  ).size,
}
export const BROKEN = checkable.filter((link) => link.status >= 400).length
export const WORKING = checkable.length - BROKEN

